{
    "requirements": [
        {"title": "Reduce FNOL to adjuster assignment time", "description": "Reduce average time from FNOL to correct adjuster assignment under 4 working hours.", "category": "functional", "priority": "must", "section_id": "S03", "source_quote": "Reduce the average time from FNOL to correct adjuster assignment from 3.8 working days to under 4 working hours for straightforward claims.", "confidence": 1},
        {"title": "Reduce misrouted claims percentage", "description": "Reduce misrouted claims from 22% to below 5%.", "category": "functional", "priority": "must", "section_id": "S03", "source_quote": "Reduce misrouted claims from 22% to below 5%.", "confidence": 1},
        {"title": "Cut manual document keying effort", "description": "Cut manual document keying effort by at least 60% within twelve months of go-live.", "category": "non_functional", "priority": "must", "section_id": "S03", "source_quote": "Cut manual document keying effort by at least 60% within twelve months of go-live.", "confidence": 1},
        {"title": "Provide concise claim summary", "description": "Give adjusters a concise, trustworthy summary of each claim.", "category": "functional", "priority": "must", "section_id": "S03", "source_quote": "Give adjusters a concise, trustworthy summary of each claim so they can start assessment without opening every attachment.", "confidence": 1},
        {"title": "Detect potential fraud", "description": "Improve early detection of potentially fraudulent claims by surfacing anomalies to SIU.", "category": "functional", "priority": "must", "section_id": "S03", "source_quote": "Improve early detection of potentially fraudulent claims by surfacing anomalies to the Special Investigations Unit (SIU), without automatically declining any claim.", "confidence": 1},
        {"title": "Build internal capability", "description": "Solution must be understandable, maintainable and retrainable by Corvane's own data science team after handover.", "category": "commercial", "priority": "must", "section_id": "S03", "source_quote": "We want a partner who will help us build lasting internal capability, not a black box. Corvane's own data science team (currently six people) must be able to understand, maintain and retrain the solution after handover.", "confidence": 1},
        {"title": "Ingest claim documents", "description": "Ingestion of claim documents from all four lodgement channels is in scope.", "category": "functional", "priority": "must", "section_id": "S04", "source_quote": "- Ingestion of claim documents from all four lodgement channels.", "confidence": 1},
        {"title": "Document classification and extraction", "description": "Document classification, data extraction and claim summarisation is in scope.", "category": "functional", "priority": "must", "section_id": "S04", "source_quote": "- Document classification, data extraction and claim summarisation.", "confidence": 1},
        {"title": "Triage claims", "description": "Triage: complexity scoring, line-of-business routing and adjuster queue assignment is in scope.", "category": "functional", "priority": "must", "section_id": "S04", "source_quote": "- Triage: complexity scoring, line-of-business routing and adjuster queue assignment.", "confidence": 1},
        {"title": "Fraud indicator flagging", "description": "Fraud-indicator flagging for referral to SIU is in scope.", "category": "functional", "priority": "must", "section_id": "S04", "source_quote": "- Fraud-indicator flagging for referral to SIU.", "confidence": 1},
        {"title": "Adjuster-facing AI outputs view", "description": "Provide an adjuster-facing view of the AI outputs.", "category": "functional", "priority": "must", "section_id": "S04", "source_quote": "- An adjuster-facing view of the AI outputs (see section 6 regarding where this must live).", "confidence": 1},
        {"title": "AI monitoring and evaluation tooling", "description": "Provide monitoring, evaluation and model governance tooling for AI components.", "category": "functional", "priority": "must", "section_id": "S04", "source_quote": "- Monitoring, evaluation and model governance tooling for the AI components.", "confidence": 1},
        {"title": "Knowledge transfer training", "description": "Provide knowledge transfer and training for Corvane's IT, data science and claims teams.", "category": "commercial", "priority": "must", "section_id": "S04", "source_quote": "- Knowledge transfer and training for Corvane's IT, data science and claims teams.", "confidence": 1}
    ],
    "open_questions": [
        {"question": "What is the definition of 'straightforward claims'?", "reason": "The term 'straightforward claims' is not defined in the RFP."}
    ]
}

{
    "requirements": [
        {"title": "Multi-channel ingestion", "description": "Ingest claim documents from various channels.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-1 Multi-channel ingestion.** The solution shall ingest claim documents from the web portal, mobile app, monitored email inboxes and scanned paper batches, and associate every document with the correct claim number in ClaimsNet.", "confidence": 1},
        {"title": "Document classification", "description": "Classify incoming documents into Corvane's taxonomy.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-2 Document classification.** The solution shall classify each incoming document into Corvane's document taxonomy (currently 27 document types, to be provided after contract award) with a confidence score.", "confidence": 1},
        {"title": "Data extraction", "description": "Extract key fields from various claim documents.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-3 Data extraction.** The solution shall extract key fields from claim forms, police reports, repair estimates and invoices, including at minimum: policy number, incident date, incident location, vehicle registration (motor), third-party details, itemised amounts and totals.", "confidence": 1},
        {"title": "Handle low-quality documents", "description": "Handle handwritten claims and low-quality images.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-4 Handwriting and image quality.** The solution shall handle handwritten claim forms and low-quality phone photographs of documents, and shall flag documents that cannot be read reliably rather than guessing.", "confidence": 1},
        {"title": "Generate claim summary", "description": "Generate a plain-language summary for each claim.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-5 Claim summarisation.** The solution shall generate a plain-language summary of each claim (no more than 200 words) for the assigned adjuster, highlighting the incident, the parties involved, amounts claimed and any missing documents. Every factual statement in the summary must be traceable to a source document.", "confidence": 1},
        {"title": "Assign complexity score", "description": "Route claims based on complexity score.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-6 Triage and routing.** The solution shall assign each claim a complexity score and route it to the appropriate line-of-business queue and adjuster tier, using rules configurable by Corvane's claims operations team without vendor involvement.", "confidence": 1},
        {"title": "Identify fraud indicators", "description": "Identify potential fraud in claims.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-7 Fraud indicators.** The solution shall identify potential fraud indicators (for example, inconsistent dates, duplicate invoices across claims, altered documents) and refer flagged claims to SIU with an explanation. The solution must never automatically decline or close a claim.", "confidence": 1},
        {"title": "Allow human review", "description": "Adjusters can accept, correct or reject AI-generated outputs.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-8 Human review.** Adjusters shall be able to accept, correct or reject every AI-generated classification, extracted field and summary. Corrections shall be captured and made available for model improvement.", "confidence": 1},
        {"title": "Draft missing info requests", "description": "Draft requests for missing documents from customers.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-9 Missing information requests.** Where mandatory documents are missing, the solution should draft a request to the customer for the adjuster to review and send.", "confidence": 1},
        {"title": "No automatic claim closure", "description": "Solution must not automatically close claims.", "category": "functional", "priority": "must", "section_id": "S07.1", "source_quote": "**FR-7 Fraud indicators.** The solution shall identify potential fraud indicators (for example, inconsistent dates, duplicate invoices across claims, altered documents) and refer flagged claims to SIU with an explanation. The solution must never automatically decline or close a claim.", "confidence": 0.9}
    ],
    "open_questions": [
        {"question": "What is the taxonomy of document types?", "reason": "The number of document types (27) is mentioned but not detailed."}
    ]
}

{
    "requirements": [
        {"title": "Single document classification", "description": "Classification and extraction for a single document should complete within 30 seconds.", "category": "non_functional", "priority": "must", "section_id": "S08", "source_quote": "**NFR-1 Performance.** Classification and extraction for a single document should complete within 30 seconds of receipt at the 95th percentile.", "confidence": 1},
        {"title": "Claim triage availability", "description": "Triage and routing for a complete claim should be available to the adjuster in real time once all FNOL documents are received.", "category": "non_functional", "priority": "must", "section_id": "S08", "source_quote": "**NFR-1 Performance.** Classification and extraction for a single document should complete within 30 seconds of receipt at the 95th percentile. Triage and routing for a complete claim should be available to the adjuster in real time once all FNOL documents are received.", "confidence": 1},
        {"title": "Peak throughput", "description": "Sustain peak volumes of 2,500 claims per day without degradation beyond NFR-1 targets.", "category": "non_functional", "priority": "must", "section_id": "S08", "source_quote": "**NFR-2 Throughput.** The solution shall sustain peak volumes of 2,500 claims per day (approximately three times the daily average), as experienced during the year-end monsoon flooding season, without degradation beyond the targets in NFR-1.", "confidence": 1},
        {"title": "99.5% availability", "description": "Achieve 99.5% availability during business hours.", "category": "non_functional", "priority": "must", "section_id": "S08", "source_quote": "**NFR-3 Availability.** The production service shall achieve 99.5% availability during business hours (08:00 to 20:00, Monday to Saturday). Planned maintenance must be scheduled outside these hours.", "confidence": 1},
        {"title": "Resilience with manual fallback", "description": "Claims must continue to flow into ClaimsNet using the existing manual process if AI components are unavailable.", "category": "non_functional", "priority": "must", "section_id": "S08", "source_quote": "**NFR-4 Resilience.** If the AI components are unavailable, claims must continue to flow into ClaimsNet using the existing manual process, with no loss of documents.", "confidence": 1},
        {"title": "Scalability for other lines of business", "description": "Architecture should allow onboarding of other lines of business and additional document types by Corvane staff without re-architecture.", "category": "non_functional", "priority": "should", "section_id": "S08", "source_quote": "**NFR-5 Scalability.** The architecture should allow other lines of business and additional document types to be onboarded by Corvane staff without re-architecture.", "confidence": 1},
        {"title": "WCAG 2.1 AA compliance", "description": "Adjuster-facing interfaces shall meet WCAG 2.1 AA standards.", "category": "non_functional", "priority": "must", "section_id": "S08", "source_quote": "**NFR-6 Accessibility and usability.** Adjuster-facing interfaces shall meet WCAG 2.1 AA.", "confidence": 1},
        {"title": "Version control for models and prompts", "description": "All models, prompts, and configuration must be version-controlled, with traceability to production outputs.", "category": "non_functional", "priority": "must", "section_id": "S08", "source_quote": "**NFR-7 Maintainability.** All models, prompts and configuration shall be version-controlled, and every production output shall be traceable to the model and configuration version that produced it.", "confidence": 1},
        {"title": "Integration with ClaimsNet SOAP services", "description": "Use existing SOAP services for integration where they exist; describe new interfaces if required.", "category": "integration", "priority": "must", "section_id": "S09", "source_quote": "**INT-1** Integration with ClaimsNet shall use the existing SOAP services where they exist. Where new interfaces are required, the bidder shall describe how they will be built and who will maintain them.", "confidence": 1},
        {"title": "Policy coverage lookups via IBM MQ", "description": "Use existing IBM MQ integration layer for policy coverage lookups; do not write to policy administration system.", "category": "integration", "priority": "must", "section_id": "S09", "source_quote": "**INT-2** Policy coverage lookups shall use the existing IBM MQ integration layer. The solution shall not write to the policy administration system.", "confidence": 1},
        {"title": "Document storage in DMS", "description": "Store documents in existing DMS as the system of record; hold working copies only for processing.", "category": "integration", "priority": "must", "section_id": "S09", "source_quote": "**INT-3** Documents shall continue to be stored in the existing DMS as the system of record. The solution may hold working copies only for as long as needed for processing, subject to the retention rules in section 8.", "confidence": 1},
        {"title": "User authentication through Active Directory", "description": "Authenticate users through Corvane's Active Directory using single sign-on.", "category": "integration", "priority": "must", "section_id": "S09", "source_quote": "**INT-4** The solution shall authenticate users through Corvane's Active Directory using single sign-on.", "confidence": 1},
        {"title": "Avoid new dependencies on nightly SFTP batch interfaces", "description": "Design should avoid new dependencies on nightly SFTP batch interfaces, which are expected to be retired within two years.", "category": "integration", "priority": "should", "section_id": "S09", "source_quote": "The nightly SFTP batch interfaces are expected to be retired within two years. Bidders should avoid designing new dependencies on them.", "confidence": 1}
    ],
    "open_questions": [
        {"question": "What is the exact definition of 'degradation beyond NFR-1 targets'?", "reason": "The quote does not specify what constitutes degradation."}
    ]
}

{
    "requirements": [
        {"title": "Budget range", "description": "The budget must be between MYR 6.5 million to MYR 8 million.", "category": "commercial", "priority": "must", "section_id": "S12", "source_quote": "The indicative budget envelope for this workstream is **MYR 6.5 million to MYR 8 million** over the initial contract term (contract award to handover)", "confidence": 1},
        {"title": "Discovery and design fixed price", "description": "A fixed price must be provided for discovery and design.", "category": "commercial", "priority": "must", "section_id": "S12", "source_quote": "- A fixed price for discovery and design.", "confidence": 1},
        {"title": "Pilot fixed or capped price", "description": "A fixed or capped price must be provided for the pilot phase.", "category": "commercial", "priority": "must", "section_id": "S12", "source_quote": "- A fixed or capped price for the pilot.", "confidence": 1},
        {"title": "Rollout phases pricing option", "description": "The bidder may choose between time-and-materials or fixed price for rollout phases, with rate cards provided.", "category": "commercial", "priority": "must", "section_id": "S12", "source_quote": "- A time-and-materials or fixed price, at the bidder's option, for the rollout phases, with rate cards.", "confidence": 1},
        {"title": "Annual licence and support costs", "description": "Annual licence and support costs must be provided for five years after handover.", "category": "commercial", "priority": "must", "section_id": "S12", "source_quote": "- Annual licence and support costs for five years after handover.", "confidence": 1},
        {"title": "Hardware procurement recommendation", "description": "Any recommended infrastructure or hardware must be provided with indicative costs, shown separately.", "category": "commercial", "priority": "must", "section_id": "S12", "source_quote": "- Any infrastructure or hardware the bidder recommends Corvane procure, with indicative costs, shown separately.", "confidence": 1},
        {"title": "Milestone-based payment", "description": "Payment must be milestone-based, with at least 15% linked to measurable outcomes.", "category": "commercial", "priority": "must", "section_id": "S12", "source_quote": "Payment will be milestone-based. Corvane expects at least 15% of the services fee to be linked to achievement of measurable outcomes, for example routing accuracy and keying effort reduction, measured after the pilot.", "confidence": 0.9},
        {"title": "Intellectual property rights", "description": "All intellectual property in custom work products must vest in Corvane.", "category": "commercial", "priority": "must", "section_id": "S12", "source_quote": "Corvane's standard terms require that all intellectual property in custom work products, including prompts, configurations, fine-tuned model weights and evaluation datasets created specifically for Corvane, vest in Corvane.", "confidence": 1}
    ],
    "open_questions": [
        {"question": "What are the specific measurable outcomes for payment milestones?", "reason": "The RFP mentions measurable outcomes but does not specify what they are."}
    ]
}

